CREATE OR REPLACE PACKAGE alliance_tips AUTHID DEFINER AS
 FUNCTION run_action(u VARCHAR2,b VARCHAR2,l VARCHAR2,a VARCHAR2,p JSON_OBJECT_T) RETURN JSON_OBJECT_T;
 PROCEDURE protect_sale(b VARCHAR2,l VARCHAR2,i VARCHAR2);
END;
/
CREATE OR REPLACE PACKAGE BODY alliance_tips AS
 PROCEDURE enabled(b VARCHAR2,l VARCHAR2) IS n NUMBER;BEGIN SELECT COUNT(*) INTO n FROM locations WHERE business_id=b AND id=l AND active=1 AND slug IN('cafeteria','cocteleria');IF n<>1 THEN alliance_security.fail(403,'FORBIDDEN','El reparto de propinas pertenece a cafetería y coctelería.');END IF;END;
 PROCEDURE protect_sale(b VARCHAR2,l VARCHAR2,i VARCHAR2) IS o JSON_OBJECT_T;BEGIN o:=alliance_operations.get_row(b,l,'tipClaims',i);IF o IS NOT NULL AND NVL(o.get_number('allocatedMinor'),0)>0 THEN alliance_security.fail(409,'TIP_DISTRIBUTED','Esta venta tiene propinas repartidas. Revisa y anula su reparto antes de corregir o anular la venta.');END IF;END;
 FUNCTION source_value(i VARCHAR2,inv JSON_OBJECT_T,voided NUMBER,credit_paid NUMBER,assigned NUMBER) RETURN JSON_OBJECT_T IS
  o JSON_OBJECT_T:=JSON_OBJECT_T();totals JSON_OBJECT_T:=inv.get_object('totals');payments JSON_ARRAY_T:=inv.get_array('payments');pay JSON_OBJECT_T;total NUMBER;tip NUMBER;paid NUMBER:=0;collected NUMBER;
 BEGIN
  total:=ROUND(NVL(totals.get_number('total'),0)*100);tip:=ROUND(NVL(totals.get_number('tip'),NVL(inv.get_number('tipAmount'),0))*100);IF payments IS NULL THEN payments:=JSON_ARRAY_T();END IF;
  FOR j IN 0..payments.get_size-1 LOOP pay:=TREAT(payments.get(j) AS JSON_OBJECT_T);IF pay.get_string('method')<>'credit' THEN paid:=paid+ROUND(NVL(pay.get_number('amount'),0)*100);END IF;END LOOP;
  paid:=LEAST(total,GREATEST(0,paid+ROUND(NVL(credit_paid,0)*100)));collected:=CASE WHEN total>0 AND voided=0 THEN ROUND(tip*paid/total) ELSE 0 END;
  o.put('saleId',i);o.put('invoice',NVL(inv.get_string('number'),i));o.put('table',NVL(inv.get_string('table'),'Venta individual'));o.put('at',inv.get_string('createdAt'));o.put('waiter',inv.get_string('waiterName'));o.put('collectedMinor',collected);o.put('allocatedMinor',assigned);o.put('availableMinor',GREATEST(0,collected-assigned));o.put('pendingMinor',CASE WHEN voided=0 THEN tip-collected ELSE 0 END);o.put('deficitMinor',GREATEST(0,assigned-collected));o.put('paidMinor',paid);o.put('totalMinor',total);o.put('payments',payments);o.put('voided',voided=1);RETURN o;
 END;
 FUNCTION sources(b VARCHAR2,l VARCHAR2) RETURN JSON_ARRAY_T IS a JSON_ARRAY_T:=JSON_ARRAY_T();o JSON_OBJECT_T;
 BEGIN
  FOR r IN(SELECT s.id,s.invoice_json,s.voided,NVL(JSON_VALUE(c.data_json,'$.allocatedMinor' RETURNING NUMBER),0) assigned,NVL(d.paid,0) credit_paid
   FROM alliance_pos_sales s LEFT JOIN alliance_pos_documents c ON c.business_id=s.business_id AND c.location_id=s.location_id AND c.entity='op_tipclaims' AND c.id=s.id
   LEFT JOIN(SELECT NVL(JSON_VALUE(data_json,'$.saleId' RETURNING VARCHAR2(80)),id) sale_id,SUM(NVL(JSON_VALUE(data_json,'$.paid' RETURNING NUMBER),0)) paid FROM alliance_pos_documents WHERE business_id=b AND location_id=l AND entity='op_debts' AND NVL(JSON_VALUE(data_json,'$.voided'),'false')<>'true' GROUP BY NVL(JSON_VALUE(data_json,'$.saleId' RETURNING VARCHAR2(80)),id)) d ON d.sale_id=s.id
   WHERE s.business_id=b AND s.location_id=l AND ((s.voided=0 AND NVL(JSON_VALUE(s.invoice_json,'$.totals.tip' RETURNING NUMBER),NVL(JSON_VALUE(s.invoice_json,'$.tipAmount' RETURNING NUMBER),0))>0) OR NVL(JSON_VALUE(c.data_json,'$.allocatedMinor' RETURNING NUMBER),0)>0) ORDER BY s.created_at DESC,s.id)
  LOOP o:=source_value(r.id,JSON_OBJECT_T(r.invoice_json),r.voided,r.credit_paid,r.assigned);a.append(o);END LOOP;RETURN a;
 END;
 FUNCTION report(b VARCHAR2,l VARCHAR2,p JSON_OBJECT_T) RETURN JSON_OBJECT_T IS
  r JSON_OBJECT_T:=JSON_OBJECT_T();rows JSON_ARRAY_T:=sources(b,l);available JSON_ARRAY_T:=JSON_ARRAY_T();history_rows JSON_ARRAY_T:=JSON_ARRAY_T();o JSON_OBJECT_T;fact JSON_OBJECT_T;received NUMBER:=0;assigned NUMBER:=0;pending NUMBER:=0;deficit NUMBER:=0;total NUMBER:=0;skip_rows NUMBER:=0;n NUMBER;revision_value VARCHAR2(64);page_rows JSON_ARRAY_T:=JSON_ARRAY_T();source_skip NUMBER:=0;source_count NUMBER:=0;query_value VARCHAR2(640);text_value VARCHAR2(4000);
 BEGIN
  IF p.has('sourceOffset') THEN source_skip:=alliance_operations.numeric_value(p,'sourceOffset',0,1000000);IF source_skip<>TRUNC(source_skip) THEN alliance_security.fail(400,'INVALID_INPUT','Página no disponible.');END IF;END IF;query_value:=TRANSLATE(LOWER(TRIM(p.get_string('query'))),'áéíóúñ','aeioun');IF LENGTH(query_value)>160 THEN alliance_security.fail(400,'INVALID_INPUT','La búsqueda admite hasta 160 caracteres.');END IF;
  IF p.has('historyOffset') THEN skip_rows:=alliance_operations.numeric_value(p,'historyOffset',0,1000000);IF skip_rows<>TRUNC(skip_rows) THEN alliance_security.fail(400,'INVALID_INPUT','Página no disponible.');END IF;END IF;
  FOR j IN 0..rows.get_size-1 LOOP o:=TREAT(rows.get(j) AS JSON_OBJECT_T);text_value:=TRANSLATE(LOWER(o.get_string('invoice')||' '||o.get_string('table')||' '||o.get_string('waiter')||' '||o.get_string('at')),'áéíóúñ','aeioun');IF query_value IS NULL OR INSTR(text_value,query_value)>0 THEN IF source_count>=source_skip AND source_count<source_skip+25 THEN page_rows.append(o);END IF;source_count:=source_count+1;END IF;received:=received+o.get_number('collectedMinor');assigned:=assigned+o.get_number('allocatedMinor');pending:=pending+o.get_number('pendingMinor');deficit:=deficit+o.get_number('deficitMinor');IF o.get_number('availableMinor')>0 THEN fact:=JSON_OBJECT_T(o.to_clob);fact.put('amountMinor',o.get_number('availableMinor'));available.append(fact);total:=total+o.get_number('availableMinor');END IF;END LOOP;
  revision_value:=LOWER(RAWTOHEX(DBMS_CRYPTO.HASH(available.to_clob,DBMS_CRYPTO.HASH_SH256)));
  SELECT COUNT(*) INTO n FROM alliance_pos_documents WHERE business_id=b AND location_id=l AND entity='op_tipdistributions';
  FOR h IN(SELECT data_json FROM alliance_pos_documents WHERE business_id=b AND location_id=l AND entity='op_tipdistributions' ORDER BY created_at DESC,id DESC OFFSET skip_rows ROWS FETCH NEXT 20 ROWS ONLY)LOOP history_rows.append(JSON_OBJECT_T(h.data_json));END LOOP;
  r.put('sources',page_rows);r.put('sourceTotal',source_count);r.put('sourceHasMore',source_skip+25<source_count);r.put('sourceOffset',source_skip);r.put('available',available);r.put('totalMinor',total);r.put('receivedMinor',received);r.put('allocatedMinor',assigned);r.put('pendingMinor',pending);r.put('deficitMinor',deficit);r.put('revision',revision_value);r.put('history',history_rows);r.put('historyTotal',n);r.put('historyHasMore',skip_rows+20<n);r.put('historyOffset',skip_rows);r.put('confirmed',TRUE);RETURN r;
 END;
 FUNCTION run_action(u VARCHAR2,b VARCHAR2,l VARCHAR2,a VARCHAR2,p JSON_OBJECT_T) RETURN JSON_OBJECT_T IS
  r JSON_OBJECT_T;batch JSON_OBJECT_T;old JSON_OBJECT_T;claim JSON_OBJECT_T;src JSON_OBJECT_T;person JSON_OBJECT_T;inv JSON_OBJECT_T;rec JSON_OBJECT_T;allocation JSON_OBJECT_T;arr JSON_ARRAY_T;names JSON_ARRAY_T;people_rows JSON_ARRAY_T:=JSON_ARRAY_T();receipt_rows JSON_ARRAY_T:=JSON_ARRAY_T();allocations JSON_ARRAY_T;
  invoice_text CLOB;identifier VARCHAR2(80);sale_id VARCHAR2(80);actor VARCHAR2(160);nm VARCHAR2(320);note_value VARCHAR2(640);reason_value VARCHAR2(640);revision_value VARCHAR2(64);request_hash VARCHAR2(64);total NUMBER;people NUMBER;base NUMBER;extra NUMBER;cents NUMBER;amount NUMBER;paid NUMBER;assigned NUMBER;voided NUMBER;found BOOLEAN;
 BEGIN
  enabled(b,l);alliance_security.require_location(u,b,l,'sales.read');
  IF a='tips_snapshot' THEN alliance_security.keys_only(p,'historyOffset,sourceOffset,query');RETURN report(b,l,p);
  ELSIF a='tips_source' THEN
   alliance_security.keys_only(p,'saleId');sale_id:=alliance_security.text_value(p,'saleId',80);BEGIN SELECT invoice_json,s.voided INTO invoice_text,voided FROM alliance_pos_sales s WHERE business_id=b AND location_id=l AND id=sale_id;inv:=JSON_OBJECT_T(invoice_text);EXCEPTION WHEN NO_DATA_FOUND THEN alliance_security.fail(404,'NOT_FOUND','Venta no disponible.');END;
   FOR h IN(SELECT data_json FROM alliance_pos_documents WHERE business_id=b AND location_id=l AND entity='op_customerpayments' AND EXISTS(SELECT 1 FROM JSON_TABLE(data_json,'$.allocations[*]' COLUMNS(debt_id VARCHAR2(80) PATH '$.debtId')) j WHERE j.debt_id=sale_id OR EXISTS(SELECT 1 FROM alliance_pos_documents d WHERE d.business_id=b AND d.location_id=l AND d.entity='op_debts' AND d.id=j.debt_id AND JSON_VALUE(d.data_json,'$.saleId')=sale_id)) ORDER BY created_at,id)LOOP rec:=JSON_OBJECT_T(h.data_json);allocations:=rec.get_array('allocations');amount:=0;FOR j IN 0..allocations.get_size-1 LOOP allocation:=TREAT(allocations.get(j) AS JSON_OBJECT_T);found:=allocation.get_string('debtId')=sale_id;IF NOT found THEN claim:=alliance_operations.get_row(b,l,'debts',allocation.get_string('debtId'));IF claim IS NOT NULL THEN found:=claim.get_string('saleId')=sale_id;END IF;END IF;IF found THEN amount:=amount+allocation.get_number('amount');END IF;END LOOP;rec.put('appliedToSale',amount);receipt_rows.append(rec);END LOOP;
   FOR h IN(SELECT t.data_json FROM alliance_pos_documents t WHERE t.business_id=b AND t.location_id=l AND t.entity='op_settlements' AND JSON_VALUE(t.data_json,'$.type')='debt_pay' AND JSON_VALUE(t.data_json,'$.paymentId') IS NULL AND (JSON_VALUE(t.data_json,'$.recordId')=sale_id OR EXISTS(SELECT 1 FROM alliance_pos_documents d WHERE d.business_id=b AND d.location_id=l AND d.entity='op_debts' AND d.id=JSON_VALUE(t.data_json,'$.recordId') AND JSON_VALUE(d.data_json,'$.saleId')=sale_id)) ORDER BY t.created_at,t.id) LOOP rec:=JSON_OBJECT_T(h.data_json);rec.put('appliedToSale',rec.get_number('amount'));person:=JSON_OBJECT_T();person.put('method',rec.get_string('method'));person.put('amount',rec.get_number('amount'));arr:=JSON_ARRAY_T();arr.append(person);rec.put('payments',arr);receipt_rows.append(rec);END LOOP;
   r:=JSON_OBJECT_T();r.put('invoice',inv);r.put('receipts',receipt_rows);RETURN r;
  END IF;
  alliance_security.require_location(u,b,l,'sales.write');alliance_pos_store.lock_scope(b,l);alliance_security.require_location(u,b,l,'sales.write');SELECT full_name INTO actor FROM users WHERE business_id=b AND id=u;
  IF a='tips_distribute' THEN
   alliance_security.keys_only(p,'id,people,names,revision,note');identifier:=alliance_security.text_value(p,'id',80,'^[a-zA-Z0-9_-]+$');people:=alliance_operations.numeric_value(p,'people',1,100);IF people<>TRUNC(people) THEN alliance_security.fail(400,'INVALID_INPUT','Escribe un número entero de personas.');END IF;
   names:=p.get_array('names');IF names IS NULL OR names.get_size<>people THEN alliance_security.fail(400,'INVALID_INPUT','Revisa las personas del reparto.');END IF;
   note_value:=p.get_string('note');IF LENGTH(note_value)>160 THEN alliance_security.fail(400,'INVALID_INPUT','La nota admite hasta 160 caracteres.');END IF;request_hash:=LOWER(RAWTOHEX(DBMS_CRYPTO.HASH(p.to_clob,DBMS_CRYPTO.HASH_SH256)));old:=alliance_operations.get_row(b,l,'tipDistributions',identifier);
   IF old IS NOT NULL THEN IF old.get_string('requestHash')<>request_hash THEN alliance_security.fail(409,'IDEMPOTENCY_REUSE','Este reparto ya tiene otros datos.');END IF;r:=report(b,l,JSON_OBJECT_T());r.put('lastDistributionId',identifier);RETURN r;END IF;
   r:=report(b,l,JSON_OBJECT_T());revision_value:=p.get_string('revision');IF revision_value IS NULL OR revision_value<>r.get_string('revision') OR r.get_number('deficitMinor')>0 THEN alliance_security.fail(409,'TIPS_CHANGED','Las propinas cambiaron. Actualiza el saldo antes de repartir.');END IF;total:=r.get_number('totalMinor');IF total<=0 THEN alliance_security.fail(409,'TIPS_EMPTY','No hay propinas cobradas pendientes de reparto.');END IF;
   base:=FLOOR(FLOOR(total/100)/people);extra:=MOD(FLOOR(total/100),people);cents:=MOD(total,100);
   FOR j IN 0..people-1 LOOP IF NOT names.get(j).is_string THEN alliance_security.fail(400,'INVALID_INPUT','Revisa los nombres.');END IF;nm:=TRIM(names.get_string(j));IF nm IS NULL OR LENGTH(nm)>80 THEN alliance_security.fail(400,'INVALID_INPUT','Escribe un nombre de hasta 80 caracteres.');END IF;person:=JSON_OBJECT_T();person.put('name',nm);person.put('amountMinor',(base+CASE WHEN j<extra THEN 1 ELSE 0 END)*100+CASE WHEN j=people-1 THEN cents ELSE 0 END);people_rows.append(person);END LOOP;
   arr:=r.get_array('available');FOR j IN 0..arr.get_size-1 LOOP src:=TREAT(arr.get(j) AS JSON_OBJECT_T);sale_id:=src.get_string('saleId');claim:=alliance_operations.get_row(b,l,'tipClaims',sale_id);IF claim IS NULL THEN claim:=JSON_OBJECT_T();assigned:=0;ELSE assigned:=claim.get_number('allocatedMinor');END IF;claim.put('allocatedMinor',assigned+src.get_number('amountMinor'));alliance_pos_store.put_document(b,l,'op_tipclaims',sale_id,claim);END LOOP;
   batch:=JSON_OBJECT_T();batch.put('status','active');batch.put('totalMinor',total);batch.put('people',people_rows);batch.put('sources',arr);batch.put('note',note_value);batch.put('requestHash',request_hash);batch.put('revision',revision_value);alliance_operations.put_row(u,b,l,'tipDistributions',identifier,batch);alliance_activity.record_event(u,b,l,'tips','tips_distribute','Registró un reparto de propinas entre '||people||' personas',identifier);r:=report(b,l,JSON_OBJECT_T());r.put('lastDistributionId',identifier);RETURN r;
  ELSIF a='tips_void' THEN
   alliance_security.keys_only(p,'distributionId,reason');IF NOT alliance_security.location_owner(u,b,l) THEN alliance_security.fail(403,'FORBIDDEN','Solo el jefe puede anular un reparto.');END IF;identifier:=alliance_security.text_value(p,'distributionId',80);reason_value:=alliance_security.text_value(p,'reason',160);batch:=alliance_operations.get_row(b,l,'tipDistributions',identifier);IF batch IS NULL THEN alliance_security.fail(404,'NOT_FOUND','Reparto no disponible.');END IF;
   IF batch.get_string('status')<>'void' THEN arr:=batch.get_array('sources');FOR j IN 0..arr.get_size-1 LOOP src:=TREAT(arr.get(j) AS JSON_OBJECT_T);sale_id:=src.get_string('saleId');claim:=alliance_operations.get_row(b,l,'tipClaims',sale_id);IF claim IS NULL OR claim.get_number('allocatedMinor')<src.get_number('amountMinor') THEN alliance_security.fail(409,'TIPS_CHANGED','Revisa el historial antes de anular este reparto.');END IF;claim.put('allocatedMinor',claim.get_number('allocatedMinor')-src.get_number('amountMinor'));alliance_pos_store.put_document(b,l,'op_tipclaims',sale_id,claim);END LOOP;batch.put('status','void');batch.put('voidAt',alliance_pos_store.stamp);batch.put('voidBy',actor);batch.put('voidReason',reason_value);alliance_pos_store.put_document(b,l,'op_tipdistributions',identifier,batch);alliance_activity.record_event(u,b,l,'tips','tips_void','Anuló un reparto de propinas: '||SUBSTR(reason_value,1,120),identifier);END IF;RETURN report(b,l,JSON_OBJECT_T());
  END IF;alliance_security.fail(400,'INVALID_INPUT','Operación de propinas no disponible.');RETURN NULL;
 END;
END;
/
